package com.example.digitalnotam.scenario.rwylim;
import com.example.digitalnotam.baseline.*;import com.example.digitalnotam.domain.Notam;import com.example.digitalnotam.scenario.common.QCodeDefaults;import com.example.digitalnotam.xml.CommonDigitalNotamBuilder;import org.w3c.dom.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
public final class RwyLimNotamProducer {
 private static final Set<String> UNPAVED=Set.of("CLAY","CORAL","EARTH","GRASS","GRAVEL","ICE","LATERITE","MACADAM","SAND","SNOW","WATER","OTHER");
 private static final Map<String,String> SIMPLE=Map.ofEntries(Map.entry("OAT","OPERATIONAL AIR TRAFFIC"),Map.entry("GAT","GENERAL AIR TRAFFIC"),Map.entry("IFR","IFR"),Map.entry("VFR","VFR"),Map.entry("HEAD","HEAD OF STATE"),Map.entry("STATE","STATE ACFT"),Map.entry("HUM","HUM"),Map.entry("HOSP","HOSP"),Map.entry("SAR","SAR"),Map.entry("EMERGENCY","EMERG"),Map.entry("MIL","MIL ACFT"),Map.entry("CIVIL","CIVIL ACFT"),Map.entry("NTL","DOMESTIC"),Map.entry("INTL","INTL"),Map.entry("HOME_BASED","HOME BASED"),Map.entry("SCHEDULED","SCHEDULED"),Map.entry("NON_SCHEDULED","NOT SCHEDULED"),Map.entry("PRIVATE","PRIVATE"),Map.entry("AIR_TRAINING","TRAINING"),Map.entry("AIR_WORK","AERIAL WORK"),Map.entry("PARTICIPANT","PARTICIPATING ACFT"),Map.entry("JET","JET ACFT"),Map.entry("PISTON","PISTON ACFT"),Map.entry("TURBOPROP","TURBOPROP ACFT"));
 private static final Map<String,String> AT=Map.ofEntries(Map.entry("LANDPLANE","LANDPLANES"),Map.entry("SEAPLANE","SEAPLANES"),Map.entry("AMPHIBIAN","AMPHIBIANS"),Map.entry("HELICOPTER","HEL"),Map.entry("GYROCOPTER","GYROCOPTERS"),Map.entry("TILT_WING","TILT WING ACFT"),Map.entry("STOL","SHORT TAKE-OFF AND LANDING ACFT"),Map.entry("GLIDER","GLIDERS"),Map.entry("HANGGLIDER","HANG-GLIDERS"),Map.entry("PARAGLIDER","PARAGLIDERS"),Map.entry("ULTRA_LIGHT","ULTRA LIGHTS"),Map.entry("BALLOON","BALLOONS"),Map.entry("UAV","UNMANNED ACFT"),Map.entry("ALL","ALL ACFT TYPES"));
 private static final Map<String,String> OP=Map.of("LANDING","LANDING","TAKEOFF","TKOF","TOUCHGO","TGL","TRAIN_APPROACH","PRACTICE LOW APPROACHES","TAXIING","TAXIING","CROSSING","CROSSING","AIRSHOW","ACFT PARTICIPATING IN AIR DISPLAY","ALL","ALL OPERATIONS");
 private static final Map<String,String> WING=Map.of("ABOVE","ACFT WITH WINGSPAN MORE THAN","AT_OR_ABOVE","ACFT WITH WINGSPAN EQUAL TO OR MORE THAN","AT_OR_BELOW","ACFT WITH WINGSPAN EQUAL TO OR LESS THAN","BELOW","ACFT WITH WINGSPAN LESS THAN"),WEIGHT=Map.of("ABOVE","ACFT MASS HEAVIER THAN","AT_OR_ABOVE","ACFT MASS EQUAL TO OR HEAVIER THAN","AT_OR_BELOW","ACFT MASS EQUAL TO OR LIGHTER THAN","BELOW","ACFT MASS LIGHTER THAN");
 private final BaselineRunwayCatalog runways=new BaselineRunwayCatalog();private final BaselineAirportHeliportCatalog airports=new BaselineAirportHeliportCatalog();private final QCodeDefaults defaults=new QCodeDefaults();private final RwyLimQCodeResolver resolver=new RwyLimQCodeResolver();
 public void produce(Document d,Notam n)throws Exception{Instant s=Instant.parse(n.effectiveStart()),e=Instant.parse(n.effectiveEnd());var a=airports.find(n.airport(),s,e);var t=runways.resolve(n.airport(),n.runwayUuid(),n.rwyTargetType(),n.runwayDirectionUuid(),s,e);Element av=eventAvailability(d);String q=resolver.resolve(av,"FATO".equals(t.runway().type())),qp[]=defaults.get(q);for(String[]x:new String[][]{{"affectedFIR",a.firDesignator()},{"selectionCode",q},{"traffic",qp[0]},{"purpose",qp[1]},{"scope","A"},{"minimumFL","000"},{"maximumFL","999"},{"coordinates",coordinates(a.latitude(),a.longitude())},{"radius","005"},{"location",a.locationIndicatorIcao().isBlank()?a.designator().substring(0,2)+"XX":a.locationIndicatorIcao()},{"effectiveStart",time(n.effectiveStart())},{"effectiveEnd",endTime(n.effectiveEnd())},{"estimatedEnd","NO"},{"permanent","NO"},{"text",itemE(av,a,t)}})CommonDigitalNotamBuilder.setNotam(d,x[0],x[1]);}
 private static String itemE(Element a,BaselineAirportHeliportCatalog.AirportBaseline airport,BaselineRunwayCatalog.ResolvedTarget t){StringBuilder out=new StringBuilder();if(airport.locationIndicatorIcao().isBlank())out.append(switch(airport.type()){case"HP"->"HELIPORT";case"LS","OTHER"->"LANDING SITE";default->"AD";}).append(' ').append(airport.name().isBlank()?"LOCATED AT "+coordinates(airport.latitude(),airport.longitude()):airport.name()).append(System.lineSeparator());if(t.runway().surfaceCompositions().stream().anyMatch(x->UNPAVED.contains(x)||x.startsWith("OTHER:")))out.append("UNPAVED ");out.append(t.runway().type()).append(' ').append(String.join("/",t.directions().stream().map(BaselineRunwayCatalog.RunwayDirectionBaseline::designator).toList())).append(' ');List<Element> us=usages(a);String type=BaselineAirportHeliportCatalog.text(us.get(0),"type");out.append(switch(type){case"CONDITIONAL"->"AVAILABLE FOR";case"RESERV"->"CLOSED, EXCEPT FOR";case"FORBID"->"PROHIBITED FOR";case"PERMIT"->"NOW AVAILABLE FOR";default->throw new IllegalArgumentException("未知 Usage type");}).append(' ').append(String.join(", ",us.stream().map(RwyLimNotamProducer::usageText).toList()));String reason="";List<String> notes=new ArrayList<>();for(Element w:BaselineAirportHeliportCatalog.directChildren(a,"annotation")){Element n=BaselineAirportHeliportCatalog.first(w,"Note");if(n==null)continue;String v=BaselineAirportHeliportCatalog.text(n,"note");if("operationalStatus".equals(BaselineAirportHeliportCatalog.text(n,"propertyName")))reason=v;else if(!v.isBlank())notes.add(v);}if(!reason.isBlank())out.append(System.lineSeparator()).append("DUE TO ").append(reason);for(String x:notes)out.append('.').append(System.lineSeparator()).append(x);String r=out.toString().stripTrailing();return (r.endsWith(".")?r:r+".").toUpperCase(Locale.ENGLISH);}
 private static String usageText(Element u){List<String> o=new ArrayList<>();Element f=BaselineAirportHeliportCatalog.first(u,"FlightCharacteristic"),a=BaselineAirportHeliportCatalog.first(u,"AircraftCharacteristic");if(f!=null)for(String x:new String[]{"type","rule","status","military","origin","purpose"})decode(o,BaselineAirportHeliportCatalog.text(f,x));if(a!=null){String type=BaselineAirportHeliportCatalog.text(a,"type");if(!type.isBlank())o.add(type.startsWith("OTHER:")?other(type):AT.get(type));decode(o,BaselineAirportHeliportCatalog.text(a,"engine"));measure(o,a,"wingSpan","wingSpanInterpretation",WING);measure(o,a,"weight","weightInterpretation",WEIGHT);}String op=BaselineAirportHeliportCatalog.text(u,"operation");o.add(op.startsWith("OTHER:")?other(op):OP.get(op));Element p=BaselineAirportHeliportCatalog.first(u,"priorPermission");if(p!=null&&!p.getTextContent().trim().isBlank()){String x="PPR "+p.getTextContent().trim()+" "+p.getAttribute("uom");for(Element w:BaselineAirportHeliportCatalog.directChildren(u,"annotation")){Element n=BaselineAirportHeliportCatalog.first(w,"Note");if(n!=null&&"priorPermission".equals(BaselineAirportHeliportCatalog.text(n,"propertyName")))x+=" "+BaselineAirportHeliportCatalog.text(n,"note");}o.add(x);}return String.join(" ",o);}
 private static void decode(List<String>o,String v){if(v.isBlank())return;if(v.startsWith("OTHER:"))o.add(other(v));else if("ALL".equals(v))o.add("ALL");else{o.add(Optional.ofNullable(SIMPLE.get(v)).orElseThrow(()->new IllegalArgumentException("缺少 E 项映射: "+v)));}}private static void measure(List<String>o,Element a,String v,String i,Map<String,String>m){Element x=BaselineAirportHeliportCatalog.first(a,v);if(x!=null&&!x.getTextContent().trim().isBlank())o.add(m.get(BaselineAirportHeliportCatalog.text(a,i))+" "+x.getTextContent().trim()+" "+x.getAttribute("uom"));}
 private static List<Element> usages(Element a){List<Element>r=new ArrayList<>();for(Element w:BaselineAirportHeliportCatalog.directChildren(a,"usage")){Element u=BaselineAirportHeliportCatalog.first(w,"ManoeuvringAreaUsage");if(u!=null)r.add(u);}return r;}private static Element eventAvailability(Document d){for(Element s:CommonDigitalNotamBuilder.all(d,CommonDigitalNotamBuilder.AIXM,"operationalStatus"))if(Set.of("LIMITED","OTHER:EXTENDED").contains(s.getTextContent().trim()))return(Element)s.getParentNode();throw new IllegalArgumentException("缺少 RWY.LIM 事件 availability");}
 private static String other(String v){return v.replaceFirst("^OTHER:","").replace('_',' ').toLowerCase(Locale.ENGLISH);}private static String time(String i){return Instant.parse(i).atZone(ZoneOffset.UTC).format(DateTimeFormatter.ofPattern("yyMMddHHmm"));}private static String endTime(String i){ZonedDateTime z=Instant.parse(i).atZone(ZoneOffset.UTC);return z.toLocalTime().equals(LocalTime.MIDNIGHT)?z.minusDays(1).format(DateTimeFormatter.ofPattern("yyMMdd"))+"2359":z.format(DateTimeFormatter.ofPattern("yyMMddHHmm"));}private static String coordinates(String la,String lo){return coord(la,2,Double.parseDouble(la)<0?"S":"N")+coord(lo,3,Double.parseDouble(lo)<0?"W":"E");}private static String coord(String v,int w,String h){double x=Math.abs(Double.parseDouble(v));int d=(int)x,m=(int)Math.round((x-d)*60);if(m==60){d++;m=0;}return("%0"+w+"d%02d%s").formatted(d,m,h);}
}
